def dump(path,obj,kind='json',exclusive=False):
 p=ROOT/path; p.parent.mkdir(parents=True,exist_ok=True)
 if exclusive and p.exists(): raise SystemExit(f'refusing to overwrite {path}')
 p.write_text(json.dumps(obj,indent=2)+'\n' if kind=='json' else yaml.safe_dump(obj,sort_keys=False,width=100))
def sha(path): return hashlib.sha256((ROOT/path).read_bytes()).hexdigest()
def read(path): return json.loads((ROOT/path).read_text())
def git(*args): return subprocess.check_output(['git',*args],cwd=ROOT,text=True).strip()
def metric(i,name,definition): return dict(id=i,name=name,unit='integer',kind='exact',definition=definition,source=f'export_results.py exact_metrics from hash-bound package JSON; export runs.measurements.counted.{i}',aggregation='per_row',resolution='one exact integer',uncertainty='none_exact')
def binding():
 sources={str(p.relative_to(ROOT)):sha(p.relative_to(ROOT)) for p in sorted((ROOT/SOURCE).rglob('*.py'))}
 sources[f'{COORD}/export_results.py']=sha(f'{COORD}/export_results.py')
 if DRIVER not in sources: raise SystemExit('driver.py must exist before binding source')
 inputs={f'{EX}/config.json':sha(f'{EX}/config.json'), f'{SOURCE}/geometry/proposed_config.json':sha(f'{SOURCE}/geometry/proposed_config.json'), f'{SOURCE}/algebra/proposed_config.json':sha(f'{SOURCE}/algebra/proposed_config.json')}
 return sources,inputs

def draft():
 if (ROOT/f'{EX}/protocol.json').exists(): raise SystemExit('draft protocol exists: do not overwrite; finish it or version/amend explicitly')
 design=read(f'{COORD}/design-contract.json')
 config={'schema':'prime-sat-five-config/v1','experiment_id':EXP,'seed':17,'geometry':read(f'{SOURCE}/geometry/proposed_config.json'),'algebra':read(f'{SOURCE}/algebra/proposed_config.json'),'sat':{'primes':[17,97,257],'digits':[2,3],'targets':[0,1,2],'curve_membership':[False,True],'curve':{'a':2,'b':3},'degree_cap':2,'seed':17,'row_cap':4096,'max_variables':6,'max_rounds_rule':'2^(2*s)+1','bit_order':'fixed_ascending','boolean_backend':'Minisat22','reference_backends':['exhaustive','z3_bitvector'],'finite_field_backend':'cvc5_feature_probe_or_explicit_unsupported','complete_pdp_separate':True},'limits':{'memory_mb':4096,'watchdog_seconds':7200,'no_wall_time_claim':True},'claims':design['lead_claims']}
 dump(f'{EX}/config.json',config,exclusive=True)
 sources,inputs=binding(); commit=git('rev-parse','HEAD')
 for path,digest in sources.items():
  try: committed=subprocess.check_output(['git','show',f'{commit}:{path}'],cwd=ROOT,stderr=subprocess.DEVNULL)
  except subprocess.CalledProcessError: raise SystemExit(f'Source must be committed before protocol identity is pinned: {path}')
  if hashlib.sha256(committed).hexdigest()!=digest: raise SystemExit(f'Dirty source cannot be protocol-pinned: {path}')
 instrument={'repo':'crypto-autoresearcher','commit':commit,'build':None,'binary_sha256':sha(Path(PYTHON).resolve()),'threads':1,'flags':{'driver':DRIVER},'env':{'PYTHONHASHSEED':'0'}}
 arm_names=[('lead1','candidate'),('lead2','candidate'),('lead3','candidate'),('lead4','candidate'),('lead5','candidate'),('aa_replay','control_aa'),('positive_controls','control_positive'),('negative_controls','control_negative')]
 arms=[{'id':i,'role':r,'description':('Full frozen aggregate package; all subcells and within-lead arms retained separately.' if i.startswith('lead') else 'Cross-lead declared controls aggregated for export; retain each subcontrol.'),'instrument':copy.deepcopy(instrument)} for i,r in arm_names]
 comps=[{'id':f'C{i}','arms':[f'lead{i}'],'differs_in':[],'design':'absolute','threshold':design['lead_claims'][i-1]['stage1']} for i in range(1,6)]
 comps.append({'id':'C-AA','arms':['lead2','aa_replay'],'differs_in':['nuisance_order'],'design':'aa'})
