 secondary=[metric('certificate_bytes','Certificate representation bytes','Serialized certificate length; sum all attempted explanations.'),metric('max_filtration_degree','Maximum reached filtration degree','Maximum degree reached by this explicitly specified instrument; not intrinsic degree of regularity.'),metric('unknown_branches','Unresolved branches','All cap-limited legal branches; one unresolved branch defeats a strong-backdoor certificate.')]
 p={'schema':'experiment.protocol/v1','protocol_id':EXP+'-v1','version':1,'created':'2026-10-29','repository':'crypto-autoresearcher','study_dir':EX,'authors':['coordinator','executor'],'links':{'experiment_id':EXP,'hypothesis_ids':[HYP],'goal_id':GOAL,'spec':f'{EX}/specification.yaml'},'question':'Which of five explicit prime-field algebra/SAT mechanisms pass their exact finite Stage1 correctness and discriminating instrument tests?','claims':[{'id':x['id'],'text':x['question']+' '+x['stage1'],'class':'exact_computation','decided_by':[f'C{i+1}'],'if_supported':'Record finite scoped observation and retain original performance obligations.','if_not_supported':'Record counterexample, failure or UNKNOWN with exact affected fixture; do not infer global closure.'} for i,x in enumerate(design['lead_claims'])]+[{'id':'OUT','text':'Cryptographic-scale ECDLP improvement, general degree-of-regularity bounds and full published MultiH XL reproduction are outside this Stage1 contract.','class':'out_of_scope','decided_by':[]}],'arms':arms,'controls':{'aa':{'present':True,'comparison':'C-AA','not_applicable_reason':None},'positive':{'present':True,'arm':'positive_controls','expected_detection':'Exact affine UNSAT and known planted strong-backdoor fixtures detected; valid group relations and saturation identities retained.','not_applicable_reason':None},'negative':{'present':True,'arm':'negative_controls','null_population':{'description':'Fixed support-matched algebraic nulls, unusable/small coset membership cells and deliberately false certificates.','generator':'Bound config seed17 and deterministic negative mutations; null is not reused as an elliptic point-decomposition claim.','n':36,'why_n':'Exact finite coverage of the 36 residual parameter cells; no statistical population inference.','matched_on':['field','variable count','monomial support','declared limits']},'not_applicable_reason':None}},'variable_ledger':ledger,'randomization':{'arm_order':'fixed','arm_order_reason':'Exact finite computations with no timed claim; deterministic order supports replay.','seed_derivation':{'method':'explicit_list','seeds':[17],'note':'Only deterministic null/control permutations use seed17; all ordinary fixtures are fixed.'},'instance_sampling':{'rule':'One aggregate package per protocol arm; complete constituent cell lists and selectors are in the hash-bound config.','independent_of_arm':True},'blinding':{'analysis_labels_masked':False,'how':'Exact invariants and prewritten stopping criteria; analysts know encodings. Independent reviewer receives committed artifacts only.'}},'sample_size':{'instances':1,'replicates':1,'warmups':0,'power':{'method':'exact','alpha':0.05,'tests_in_family':1,'correction':'none','passes':True,'note':'Exact finite computations, not a sampled significance test. Each lead reports its own cell set; no pooled effect estimate.'},'preflight_runtime':{'fixed_seconds':None,'per_sample_seconds':None,'threads':1,'estimated_total_seconds':7200,'measured_on':'Conservative planning watchdog only, not a measured runtime estimate; no scientific preflight run has occurred.'}},'metrics':{'primary':prim,'secondary':secondary},'measurement':{'isolation_required':'none','warmups':0,'order':'sequential','clock':'none','counters':[],'record':['source_sha256','input_sha256','python_version','dependency_versions','host','command','seed','caps','validity','restored'],'timed_primary_justification':None},'execution':{'backend':'local','measurement_class':'search','timeout_seconds':7200,'checkpoint':{'policy':'none','interval_seconds':None,'grace_seconds':None,'restore_validation':'none','after_restore':{'wall_time':'invalid','counted_units':'valid'}},'retries':{'infrastructure_only':True,'max_attempts':1}},'stopping_rules':[{'rule':'Execute precisely the frozen finite configs once, with their A/A, positive and negative controls; no scaling after inspecting data.','kind':'fixed_n','preregistered':True},{'rule':'Stop affected computation at declared variable/degree/row/memory cap; preserve UNKNOWN and completed rows.','kind':'budget','preregistered':True},{'rule':'Certificate mismatch or oracle disagreement invalidates affected scientific comparison; preserve raw record and do not silently rerun.','kind':'invalidation','preregistered':True}],'invalidation_rules':['Wrong source/input hash, dropped exceptional branch, rejected positive control, non-reproducible exact output, corrupted certificate, or inconsistent finite-domain model set.'],'decision_rule':{'text':'For C1-C5 report exact correctness and instrument outcomes separately. A successful correspondence/instrument gate does not support the untested original performance hypothesis. A/A exact invariants must agree; differing operation counts are reported as order sensitivity. Any unresolved branch makes the corresponding completeness/strong-backdoor assertion UNKNOWN.','comparison_ids':['C1','C2','C3','C4','C5'],'statistic':'Per-cell exact identities, model-set equality, integer counts and cap status; no pooling across distinct lead questions.','interval':'None; exact finite cases only.','multiple_comparison_correction':'none','effect_size_measure':'Integer differences and paired ratios descriptive only; no extrapolation.','verdict_vocabulary':['exact_match','counterexample','unknown','invalid','not_applicable']},'analysis_plan':{'script':{'path':'../../'+f'{COORD}/export_results.py','sha256':sha(f'{COORD}/export_results.py')},'inputs':['raw-result.json'],'outputs':['check.stdout.log','export.json','report.md'],'blinded':False,'frozen_before_data':True},'reporting':{'export_schema':'experiment.export/v1','review_schema':'experiment.review/v1','graphs':[f'{EX}/reports/diagram.svg'],'report_dir':f'{EX}/reports'},'inadmissible':design['shared_rules']+['A source-inspired construction calibration is not reproduction of a published performance table.'],'literature':[{'ref':'https://eprint.iacr.org/2026/408','provenance':'retrieved','claim':'Partial degree-layer source; structured elliptic rank transfer remains unproved.'},{'ref':'https://eprint.iacr.org/2025/2060','provenance':'retrieved','claim':'Multi-homogeneous XL is external motivation, not claimed reproduced by simple block filtering.'},{'ref':'https://arxiv.org/html/2402.17927v1','provenance':'retrieved','claim':'Native finite-field conflict explanations; no ECDLP performance transfer.'}],'amendments':[],'freeze':{'status':'draft','protocol_sha256':None,'commit':None,'frozen_at':None,'filed_before_affected_data':None},'extensions':{'design_contract':design,'within_lead_config':config,'source_sha256':sources,'input_sha256':inputs,'aggregate_export_note':'Eight package arms each have one aggregate instance. Each raw package retains all internal cells and arm labels; do not collapse unknowns or mask different domains.'}}
 dump(f'{EX}/protocol.json',p,exclusive=True)
 h={'id':HYP,'question_id':'RQ-PFDR-ae2fba','statement':'Five separately judged mechanisms may pass exact finite correctness gates and expose useful algebraic structure on the declared fixtures; no shared success or asymptotic conclusion is asserted.','mechanism':[x['question'] for x in design['lead_claims']],'assumptions':design['shared_rules'],'asymptotic_claim':None,'proof_search_map':{'not_applicable_reason':'Stage1 exact finite correspondence/certificate and instrument discrimination; no new general theorem is claimed.'},'predictions':[{'metric':x['id'],'direction':'different','minimum_effect':x['stage1']} for x in design['lead_claims']],'test_boundary':{'instances':[f'{EX}/config.json'],'parameters':config,'implementation':SOURCE,'budget':{'maximum_memory_gb':4,'maximum_workers':1}},'falsification_conditions':['A checked counterexample refutes the corresponding finite correctness claim.','Any unsolved legal branch defeats that strong-backdoor certificate.','No savings in complete charged work is negative only for the tested instrument/configuration.'],'interpretation_limits':[x['unresolved'] for x in design['lead_claims']],'status':'specified','proposed_by':'coordinator','idea_ids':[x['proposal'] for x in design['lead_claims']]}
 dump(f'ledger/hypotheses/{HYP}.yaml',{'hypothesis':h},'yaml',exclusive=True)
 s={'id':EXP,'hypothesis_id':HYP,'goal_id':GOAL,'version':1,'title':'Five prime-field algebra and SAT leads: exact finite Stage1 tests','status':'review_required','objective':p['question'],'inputs':{'config':f'{EX}/config.json'},'input_bindings':{'source':[{'path':k,'sha256':v} for k,v in sources.items()],'fixtures':[{'path':k,'sha256':v} for k,v in inputs.items()]},'controls':p['controls'],'independent_variables':ledger['independent'],'metrics':p['metrics'],'scale_relevance':{'tier':'toy','justification':'Exact finite fields and finite domains from frozen config; no extrapolation.','correspondence':None},'replication':{'seeds':[17],'independent_instances':1},'budget':{'enforcement':'advisory','maximum_memory_gb':4,'maximum_workers':1,'maximum_runs':1},'stopping_rules':[x['rule'] for x in p['stopping_rules']],'invalidation_rules':p['invalidation_rules'],'success_criterion':'C1-C5: independently verified exact finite outcomes, with complete domain/chart coverage for every completeness assertion. Original performance hypotheses remain undecided unless their full charged-work criterion is actually evaluated.','falsification_criterion':'C1-C5: explicit counterexample, invalid certificate or unresolved legal branch rejects the respective finite assertion; censored resource cells remain UNKNOWN.','decision_impact':{'on_positive':'Retain distinct finite observations and select follow-up only after independent review; no official support transition.','on_negative':'Record affected encoding or instrument counterexample with scope; repair under an additive amendment, or close only that tested variant after review.'},'variable_ledger':ledger,'prediction_provenance':[{'prediction':x['id'],'first_recorded_in':f'ledger/proposals/{x["proposal"]}.yaml','written_at':'2026-10-29','data_seen':[],'sample_status':'out_of_sample','overlap':'Exact present instrument not run; literature and prior residual negatives motivate tests, not fitted outcomes.'} for x in design['lead_claims']],'transfer_obligations':[],'required_artifacts':['manifest.yaml','raw-result.json',*GENERATED,'export.json','reports/report.md','reports/diagram.svg','reports/report.pdf'],'assigned_to':'executor','approved_by':None,'frozen':False,'execution_authorized':False,'execution_plan':{'protocol_hashes':{},'trial_plan':f'{EX}/trial-plan.json','queue':QUEUE},'stage1_claims':design['lead_claims']}
