 if p['freeze']['status']!='frozen': raise SystemExit('protocol must be frozen before preview')
 s=yaml.safe_load((ROOT/f'{EX}/specification.yaml').read_text())['experiment']
 if s['status']!='review_required': raise SystemExit('canonical status must remain review_required')
